function getMachine(value)
{
	const machine = Machines.find(item => item.value === value);
	if (!machine)
		throw new Error("Select a valid target machine.");
	return machine;
}

function getTarget(value)
{
	const target = Targets.find(item => item.value === value);
	if (!target)
		throw new Error("Select a valid program format.");
	return target;
}

function parseRomSize(value)
{
	const match = String(value).trim().match(/^(\d+(?:\.\d+)?)\s*(KB|MB)?$/i);
	if (!match)
		return NaN;

	const size = Number(match[1]) * (match[2] && match[2].toUpperCase() === "MB" ? 1024 : 1);
	return Number.isInteger(size) ? size : NaN;
}

function formatRomSize(sizeInKb)
{
	return sizeInKb >= 1024 && sizeInKb % 1024 === 0
		? `${sizeInKb / 1024} MB`
		: `${sizeInKb} KB`;
}

function parseIntegerExpression(expression)
{
	if (typeof expression !== "string")
		return undefined;

	const tokens = [];
	const tokenExpression = /\s*(0x[0-9a-f]+|\d+|[()+*/-])\s*/igy;
	let offset = 0;
	while (offset < expression.length)
	{
		tokenExpression.lastIndex = offset;
		const match = tokenExpression.exec(expression);
		if (!match)
			return undefined;
		tokens.push(match[1]);
		offset = tokenExpression.lastIndex;
	}

	let position = 0;
	const parsePrimary = () =>
	{
		const token = tokens[position++];
		if (token === "(")
		{
			const value = parseExpression();
			if (tokens[position++] !== ")")
				throw new Error("Invalid integer expression.");
			return value;
		}
		if (!token || !/^(?:0x[0-9a-f]+|\d+)$/i.test(token))
			throw new Error("Invalid integer expression.");
		return /^0x/i.test(token) ? Number.parseInt(token.slice(2), 16) : Number(token);
	};
	const parseUnary = () =>
	{
		if (tokens[position] === "+" || tokens[position] === "-")
		{
			const sign = tokens[position++] === "-" ? -1 : 1;
			return sign * parseUnary();
		}
		return parsePrimary();
	};
	const parseProduct = () =>
	{
		let value = parseUnary();
		while (tokens[position] === "*" || tokens[position] === "/")
		{
			const operator = tokens[position++];
			const operand = parseUnary();
			value = operator === "*" ? value * operand : value / operand;
		}
		return value;
	};
	const parseExpression = () =>
	{
		let value = parseProduct();
		while (tokens[position] === "+" || tokens[position] === "-")
		{
			const operator = tokens[position++];
			const operand = parseProduct();
			value = operator === "+" ? value + operand : value - operand;
		}
		return value;
	};

	try
	{
		const value = parseExpression();
		return position === tokens.length && Number.isSafeInteger(value) ? value : undefined;
	}
	catch
	{
		return undefined;
	}
}

function parseAppIdentifier(value, setting)
{
	const answer = String(value).trim();
	const quotedString = answer.match(/^"(..)"$/);
	if (quotedString)
		return quotedString[1];

	if (/^\d+$/.test(answer))
	{
		const number = Number(answer);
		if (number <= 65535)
			return number;
	}
	else if (/^0x[0-9a-f]{1,4}$/i.test(answer))
		return Number.parseInt(answer.slice(2), 16);

	throw new Error(`${setting} must be a quoted two-character string, a decimal number, or a 16-bit hexadecimal number.`);
}

function getLibraryModules()
{
	const modules = [];
	const visitDirectory = directory =>
	{
		for (const entry of fs.readdirSync(directory, { withFileTypes: true }))
		{
			const entryPath = path.join(directory, entry.name);
			if (entry.isDirectory())
				visitDirectory(entryPath);
			else if (entry.isFile() && /\.c$/i.test(entry.name))
				modules.push(path.relative(SourceDir, entryPath).replace(/\.[^.]+$/, "").split(path.sep).join("/"));
		}
	};
	visitDirectory(SourceDir);
	return modules.sort();
}

function getTemplateDefaults(machine)
{
	const templateDir = path.join(ProjectsDir, machine.template);
	const projectConfig = fs.readFileSync(path.join(templateDir, "project_config.js"), "utf8");
	const msxglConfig = fs.readFileSync(path.join(templateDir, "msxgl_config.h"), "utf8");
	const modulesMatch = projectConfig.match(/^LibModules\s*=\s*\[([^\]]*)\];/m);
	if (!modulesMatch)
		throw new Error("Could not find LibModules in the project template.");

	const supportedModes = ["1", "12", "122P"].includes(machine.value) ? VdpModes.slice(0, 4) : VdpModes;
	const modes = supportedModes.map(mode =>
	{
		const match = msxglConfig.match(new RegExp(`^\\s*#define\\s+VDP_USE_MODE_${mode.name}\\s+(TRUE|FALSE)`, "m"));
		if (!match)
			throw new Error(`Could not find VDP_USE_MODE_${mode.name} in the project template.`);
		return { ...mode, enabled: match[1] === "TRUE" };
	});

	return {
		modules: [...modulesMatch[1].matchAll(/"([^"]+)"/g)].map(match => match[1]),
		modes
	};
}

function getOptions(machineValue)
{
	const machine = getMachine(machineValue);
	const defaults = getTemplateDefaults(machine);
	return {
		machines: Machines.map(({ label, value }) =>
			({ label, value, translationId: `Machine.MSX${value}` })),
		targets: Targets.map(({ label, value, mapped, step, min, max }) =>
			({ label, value, mapped: Boolean(mapped), step, min, max, translationId: `Target.${value}` })),
		modes: defaults.modes.map(mode => ({ ...mode, translationId: `VDP.Mode.${mode.name}` })),
		modules: getLibraryModules(),
		defaultModules: defaults.modules,
		extensions: EmulatorExtensions.map(([value, label]) =>
			({ value, label, translationId: `Emul.Ext.${value.slice(4)}` }))
	};
}

function replaceSetting(config, setting, value)
{
	const escapedSetting = setting.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const expression = new RegExp(`^([ \\t]*${escapedSetting}[ \\t]*=[ \\t]*)[\\s\\S]*?(;[ \\t]*(?:\\/\\/[^\\r\\n]*)?)$`, "gm");
	const matches = config.match(expression);
	if (!matches || matches.length !== 1)
		throw new Error(`Could not update ${setting} in project_config.js.`);

	const formattedValue = Array.isArray(value)
		? `[ ${value.map(item => JSON.stringify(item)).join(", ")} ]`
		: JSON.stringify(value);
	return config.replace(expression, (_match, prefix, suffix) => `${prefix}${formattedValue}${suffix}`);
}

function setOrAppendSetting(config, setting, value)
{
	const escapedSetting = setting.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const expression = new RegExp(`^[ \\t]*${escapedSetting}[ \\t]*=[ \\t]*[\\s\\S]*?;[ \\t]*(?:\\/\\/[^\\r\\n]*)?$`, "gm");
	const matches = config.match(expression);
	if (matches && matches.length > 1)
		throw new Error(`Multiple active definitions of ${setting} found in project_config.js.`);
	if (matches)
		return replaceSetting(config, setting, value);

	const commentedExpression = new RegExp(`^([ \\t]*)//[ \\t]*(${setting}[ \\t]*=[ \\t]*)[^;\\r\\n]+(;[^\\r\\n]*)$`, "gm");
	if (commentedExpression.test(config))
	{
		let replaced = false;
		return config.replace(commentedExpression, (match, indent, assignment, suffix) =>
		{
			if (replaced)
				return match;
			replaced = true;
			return `${indent}${assignment}${JSON.stringify(value)}${suffix}`;
		});
	}

	throw new Error(`Could not find a project_config.js setting for ${setting}.`);
}

function replaceDefine(config, name, value)
{
	const expression = new RegExp(`^(\\s*#define\\s+${name}\\s+)\\w+`, "m");
	if (!expression.test(config))
		throw new Error(`Could not find #define ${name} in msxgl_config.h.`);
	return config.replace(expression, `$1${value ? "TRUE" : "FALSE"}`);
}

function getSelectedScreenMode(config)
{
	const modesByPriority = [
		VdpModes.filter(mode => mode.kind === "text"),
		VdpModes.filter(mode => mode.kind === "tiles"),
		VdpModes.filter(mode => mode.kind === "bitmap")
	];

	for (const modes of modesByPriority)
	{
		for (const mode of modes)
		{
			if (new RegExp(`^\\s*#define\\s+VDP_USE_MODE_${mode.name}\\s+TRUE\\b`, "m").test(config))
				return mode;
		}
	}

	throw new Error("Enable at least one supported VDP screen mode.");
}

function configureSource(source, projectName, screenMode, customISR)
{
	const setModeExpression = /^[ \t]*VDP_SetMode\(VDP_MODE_[A-Z0-9_]+\);[ \t]*$/gm;
	if (!setModeExpression.test(source))
		throw new Error("Could not find VDP_SetMode in the C template.");
	source = source.replace(setModeExpression, `\tVDP_SetMode(${screenMode.mode});`);

	const fontExpression = /^[ \t]*Print_Set(?:Text|Bitmap)Font\([^;\r\n]+;[ \t]*$/gm;
	if (!fontExpression.test(source))
		throw new Error("Could not find a font setup call in the C template.");
	const fontSetup = screenMode.kind === "bitmap"
		? "\tPrint_SetBitmapFont(g_Font_MGL_Sample6);"
		: "\tPrint_SetTextFont(g_Font_MGL_Sample6, 1);";
	source = source.replace(fontExpression, fontSetup);

	const titleExpression = /^[ \t]*Print_DrawText\(MSX_GL" The MSX Game Library"\);[ \t]*$/gm;
	if (!titleExpression.test(source))
		throw new Error("Could not find the title Print_DrawText call in the C template.");
	source = source.replace(titleExpression, `\tPrint_DrawText("${projectName}");`);

	const cursorX = screenMode.name === "T1" ? 39 : screenMode.name === "T2" ? 79 : 31;
	if (screenMode.kind !== "bitmap")
		source = source.replace("Print_SetPosition(255-8, 0);", `Print_SetPosition(${cursorX}, 0);`);
	else
		source = source.replace("Print_SetPosition(39, 0);", "Print_SetPosition(255-8, 0);");

	if (customISR && customISR !== "NONE")
	{
		if (!source.includes("void main()"))
			throw new Error("Could not find main() in the C template.");
		const handlers = ["void VDP_InterruptHandler() {}"];
		if (customISR === "VHBLANK")
			handlers.push("void VDP_HBlankHandler() {}");
		else if (customISR === "V9990")
			handlers.push("void V9_InterruptVBlank() {}", "void V9_InterruptHBlank() {}", "void V9_InterruptCommand() {}");
		source = source.replace("void main()", `${handlers.join("\n")}\n\nvoid main()`);
	}

	return source;
}

function validateProjectName(name)
{
	if (typeof name !== "string" || !/^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(name))
		throw new Error("Use a project name starting with a letter or number and containing only letters, numbers, hyphens or underscores.");
	if (/^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$/i.test(name))
		throw new Error("This project name is reserved by Windows.");
}

function getProjectDirectory(name)
{
	validateProjectName(name);
	if (ReservedProjectNames.has(name.toLowerCase()))
		throw new Error("Select a project directory, not a template directory.");
	const projectDir = path.join(ProjectsDir, name);
	const projectConfigPath = path.join(projectDir, "project_config.js");
	const msxglConfigPath = path.join(projectDir, "msxgl_config.h");
	if (!fs.existsSync(projectDir) || !fs.lstatSync(projectDir).isDirectory() ||
		!fs.existsSync(projectConfigPath) || !fs.lstatSync(projectConfigPath).isFile() ||
		!fs.existsSync(msxglConfigPath) || !fs.lstatSync(msxglConfigPath).isFile())
		throw new Error(`Project configuration files were not found for '${name}'.`);
	return { projectDir, projectConfigPath, msxglConfigPath };
}

function listProjects()
{
	return fs.readdirSync(ProjectsDir, { withFileTypes: true })
		.filter(entry => entry.isDirectory() && !ReservedProjectNames.has(entry.name.toLowerCase()))
		.map(entry =>
		{
			const projectDir = path.join(ProjectsDir, entry.name);
			const hasConfigs = fs.existsSync(path.join(projectDir, "project_config.js")) &&
				fs.existsSync(path.join(projectDir, "msxgl_config.h"));
			if (!hasConfigs)
				return null;
			return {
				name: entry.name,
				buildable: fs.existsSync(path.join(projectDir, "build.bat")) ||
					fs.existsSync(path.join(projectDir, "build.sh"))
			};
		})
		.filter(Boolean)
		.sort((left, right) => left.name.localeCompare(right.name));
}

function readWizardConfig()
{
	if (!fs.existsSync(WizardConfigPath))
	{
		const initialConfig = {
			lastOption: "create",
			projectName: "",
			language: "en",
			buildActions: [...DefaultBuildActions]
		};
		fs.writeFileSync(WizardConfigPath, `${JSON.stringify(initialConfig, null, "\t")}\n`);
		return initialConfig;
	}
	const config = JSON.parse(fs.readFileSync(WizardConfigPath, "utf8"));
	if (!config || !WizardOptions.includes(config.lastOption) ||
		typeof config.projectName !== "string" ||
		(config.language !== undefined && !WizardLanguages.includes(config.language)) ||
		(config.buildActions !== undefined && !Array.isArray(config.buildActions)))
		throw new Error("projects/wizard.cfg must contain a valid lastOption and projectName.");
	if (config.buildActions !== undefined)
		validateBuildActions(config.buildActions, true);
	if (config.projectName)
		validateProjectName(config.projectName);
	if (config.language === undefined || config.buildActions === undefined)
	{
		config.language = config.language || "en";
		config.buildActions = config.buildActions || [...DefaultBuildActions];
		fs.writeFileSync(WizardConfigPath, `${JSON.stringify(config, null, "\t")}\n`);
	}
	return config;
}

function saveWizardConfig(config)
{
	if (!config || !WizardOptions.includes(config.lastOption) ||
		typeof config.projectName !== "string" || config.projectName.length > 64 ||
		(config.language !== undefined && !WizardLanguages.includes(config.language)) ||
		(config.buildActions !== undefined && !Array.isArray(config.buildActions)))
		throw new Error("The selected wizard option or project name is invalid.");
	if (config.projectName)
		validateProjectName(config.projectName);
	const previousConfig = config.language === undefined || config.buildActions === undefined
		? readWizardConfig()
		: undefined;
	const savedConfig = {
		lastOption: config.lastOption,
		projectName: config.projectName,
		language: config.language || previousConfig.language || "en",
		buildActions: validateBuildActions(
			config.buildActions === undefined ? previousConfig.buildActions : config.buildActions,
			true
		)
	};
	fs.writeFileSync(WizardConfigPath, `${JSON.stringify(savedConfig, null, "\t")}\n`);
	return savedConfig;
}

function validateArray(values, allowed, label)
{
	if (!Array.isArray(values) || values.some(value => !allowed.includes(value)))
		throw new Error(`Select valid ${label}.`);
	return [...new Set(values)];
}

function isCustomISRRequired(target, installRAMISR)
{
	return installRAMISR !== "RAMISR_NONE" || target === "ROM_48K_ISR" ||
		target === "ROM_64K_ISR" || target === "ROM_NEO8" || target === "ROM_NEO16";
}

function configureProject(form, projectName, projectConfig, msxglConfig)
{
	validateProjectName(projectName);
	const machine = getMachine(form.machine);
	const target = getTarget(form.target);
	projectConfig = replaceSetting(projectConfig, "ProjName", projectName);
	projectConfig = replaceSetting(projectConfig, "Machine", machine.value);
	projectConfig = replaceSetting(projectConfig, "Target", target.value);

	const installRAMISR = form.installRAMISR;
	if (!InstallISRChoices.includes(installRAMISR))
		throw new Error("Select a valid RAM ISR installation mode.");
	projectConfig = setOrAppendSetting(projectConfig, "InstallRAMISR", installRAMISR);
	let customISR;
	if (isCustomISRRequired(target.value, installRAMISR))
	{
		customISR = form.customISR;
		if (!CustomISRChoices.includes(customISR))
			throw new Error("Select a valid custom ISR type.");
		projectConfig = setOrAppendSetting(projectConfig, "CustomISR", customISR);
	}

	if (form.advanced === true)
	{
		const romSkipBoot = form.romSkipBoot;
		const romSkipBootKey = form.romSkipBootKey;
		if (!RomSkipBootChoices.includes(romSkipBoot))
			throw new Error("Select a valid ROM boot skipping mode.");
		if (!RomSkipBootKeys.includes(romSkipBootKey))
			throw new Error("Select a valid ROM boot skipping key.");
		projectConfig = setOrAppendSetting(projectConfig, "ROMSkipBoot", romSkipBoot);
		projectConfig = setOrAppendSetting(projectConfig, "ROMSkipBootKey", romSkipBootKey);
		for (const setting of ["CheckVersion", "ROMDelayBoot", "AddROMSignature"])
		{
			if (typeof form[setting] !== "boolean")
				throw new Error(`Select whether ${setting} is enabled.`);
			projectConfig = setOrAppendSetting(projectConfig, setting, form[setting]);
		}

		const defaults = getTemplateDefaults(machine);
		const modules = validateArray(form.modules, getLibraryModules(), "library modules");
		const modes = validateArray(form.modes, defaults.modes.map(mode => mode.name), "screen modes");
		if (!modes.length)
			throw new Error("Enable at least one supported VDP screen mode.");

		projectConfig = replaceSetting(projectConfig, "LibModules", modules);
		for (const mode of VdpModes)
			msxglConfig = replaceDefine(msxglConfig, `VDP_USE_MODE_${mode.name}`, modes.includes(mode.name));

		if (typeof form.appSignature !== "boolean")
			throw new Error("Select whether to add an application signature.");
		projectConfig = replaceSetting(projectConfig, "AppSignature", form.appSignature);
		if (form.appSignature)
		{
			projectConfig = replaceSetting(projectConfig, "AppCompany", parseAppIdentifier(form.appCompany, "AppCompany"));
			projectConfig = replaceSetting(projectConfig, "AppID", parseAppIdentifier(form.appID, "AppID"));
		}

		const extensions = validateArray(form.extensions, EmulatorExtensions.map(([name]) => name), "emulator extensions");
		for (const [name] of EmulatorExtensions)
		{
			const expression = new RegExp(`^([ \\t]*//[ \\t]*)(${name}[ \\t]*=[ \\t]*)[^;\\r\\n]+(;[^\\r\\n]*)$`, "gm");
			if (expression.test(projectConfig))
			{
				projectConfig = projectConfig.replace(expression, (_match, _comment, assignment, suffix) =>
					`${assignment}${extensions.includes(name)}${suffix}`);
			}
			else
				projectConfig = setOrAppendSetting(projectConfig, name, extensions.includes(name));
		}

		if (!PortAChoices.includes(form.emulPortA))
			throw new Error("Select a valid joystick port A device.");
		projectConfig = setOrAppendSetting(projectConfig, "EmulPortA", form.emulPortA);
		if (!PortAChoices.includes(form.emulPortB))
			throw new Error("Select a valid joystick port B device.");
		projectConfig = setOrAppendSetting(projectConfig, "EmulPortB", form.emulPortB);

		if (typeof form.emulator !== "string" || typeof form.emul2ndCart !== "string")
			throw new Error("Enter valid emulator and secondary cartridge paths.");
		const emulator = form.emulator.trim();
		const secondCart = form.emul2ndCart.trim();
		projectConfig = setOrAppendSetting(projectConfig, "Emulator", emulator);
		projectConfig = setOrAppendSetting(projectConfig, "Emul2ndCart", secondCart);

		for (const setting of ["Verbose", ...LogSettings])
		{
			if (typeof form[setting] !== "boolean")
				throw new Error(`Select whether ${setting} is enabled.`);
			projectConfig = setOrAppendSetting(projectConfig, setting, form[setting]);
		}
		if (typeof form.LogFileName !== "string")
			throw new Error("Enter a valid build log filename.");
		projectConfig = setOrAppendSetting(projectConfig, "LogFileName", form.LogFileName.trim());
		if (typeof form.Analyzer !== "boolean" || typeof form.AnalyzerCSV !== "boolean" ||
			typeof form.Standalone !== "boolean")
			throw new Error("Select valid build and analyzer options.");
		if (!AnalyzerOutputs.includes(form.AnalyzerOutput) || !AnalyzerSorts.includes(form.AnalyzerSort))
			throw new Error("Select valid analyzer output and sort options.");
		if (typeof form.AnalyzerReport !== "string" || !/^[ASMCV]*$/.test(form.AnalyzerReport) ||
			typeof form.AnalyzerSeparator !== "string" || form.AnalyzerSeparator.length !== 1 ||
			/[\r\n]/.test(form.AnalyzerSeparator))
			throw new Error("Enter valid analyzer report fields and CSV separator.");
		for (const setting of ["Analyzer", "AnalyzerCSV", "Standalone"])
			projectConfig = setOrAppendSetting(projectConfig, setting, form[setting]);
		for (const setting of ["AnalyzerOutput", "AnalyzerReport", "AnalyzerSort", "AnalyzerSeparator"])
			projectConfig = setOrAppendSetting(projectConfig, setting, form[setting]);
	}

	if (target.mapped)
	{
		const romSize = parseRomSize(form.romSize);
		if (!Number.isInteger(romSize) || romSize < target.min || romSize > target.max || romSize % target.step !== 0)
			throw new Error(`ROM size must be between ${formatRomSize(target.min)} and ${formatRomSize(target.max)}, in multiples of ${formatRomSize(target.step)}.`);
		projectConfig = setOrAppendSetting(projectConfig, "ROMSize", romSize);
	}

	const selectedScreenMode = getSelectedScreenMode(msxglConfig);
	if (selectedScreenMode.kind === "bitmap")
		msxglConfig = replaceDefine(msxglConfig, "PRINT_USE_TEXT", false);
	return { projectConfig, msxglConfig, machine, target, selectedScreenMode, customISR };
}

function createProject(form)
{
	validateProjectName(form.projectName);
	const projectDir = path.join(ProjectsDir, form.projectName);
	if (fs.existsSync(projectDir))
		throw new Error(`Project directory already exists: ${projectDir}`);

	const machine = getMachine(form.machine);
	const templateDir = path.join(ProjectsDir, machine.template);
	const configured = configureProject(
		form,
		form.projectName,
		fs.readFileSync(path.join(templateDir, "project_config.js"), "utf8"),
		fs.readFileSync(path.join(templateDir, "msxgl_config.h"), "utf8")
	);
	const source = configureSource(
		fs.readFileSync(path.join(templateDir, "template.c"), "utf8"),
		form.projectName,
		configured.selectedScreenMode,
		configured.customISR
	);

	fs.mkdirSync(projectDir);
	try
	{
		fs.writeFileSync(path.join(projectDir, "project_config.js"), configured.projectConfig);
		fs.writeFileSync(path.join(projectDir, "msxgl_config.h"), configured.msxglConfig);
		fs.writeFileSync(path.join(projectDir, `${form.projectName}.c`), source);
		fs.copyFileSync(path.join(templateDir, "build.bat"), path.join(projectDir, "build.bat"));
		fs.copyFileSync(path.join(templateDir, "build.sh"), path.join(projectDir, "build.sh"));
	}
	catch (error)
	{
		fs.rmSync(projectDir, { recursive: true, force: true });
		throw error;
	}

	return { projectName: form.projectName, projectPath: projectDir };
}

function getProjectSettings(projectName)
{
	const project = getProjectDirectory(projectName);
	const projectConfig = fs.readFileSync(project.projectConfigPath, "utf8");
	const msxglConfig = fs.readFileSync(project.msxglConfigPath, "utf8");
	const readValue = (config, name) =>
	{
		const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
		const match = config.match(new RegExp(`^[ \\t]*${escapedName}[ \\t]*=[ \\t]*([\\s\\S]*?);[ \\t]*(?:\\/\\/[^\\r\\n]*)?$`, "m"));
		return match ? match[1].trim() : undefined;
	};
	const parseValue = (config, name, fallback) =>
	{
		const raw = readValue(config, name);
		if (raw === undefined)
			return fallback;
		if (raw === "true")
			return true;
		if (raw === "false")
			return false;
		if (/^"(?:[^"\\]|\\.)*"$/.test(raw))
			return JSON.parse(raw);
		if (/^(?:0x[0-9a-f]+|\d+)$/i.test(raw))
			return Number(raw);
		return fallback;
	};
	const machineValue = parseValue(projectConfig, "Machine", "1");
	const machine = Machines.find(item => item.value === String(machineValue));
	if (!machine)
		throw new Error(`Project '${projectName}' uses an unsupported machine setting: ${machineValue}.`);
	const supportedModes = ["1", "12", "122P"].includes(machine.value) ? VdpModes.slice(0, 4) : VdpModes;
	const modes = supportedModes
		.filter(mode => new RegExp(`^\\s*#define\\s+VDP_USE_MODE_${mode.name}\\s+TRUE\\b`, "m").test(msxglConfig))
		.map(mode => mode.name);
	const modulesMatch = projectConfig.match(/^[ \t]*LibModules[ \t]*=[ \t]*\[([\s\S]*?)\][ \t]*;/m);
	const modules = modulesMatch
		? [...modulesMatch[1].matchAll(/"([^"]+)"/g)].map(match => match[1])
		: getTemplateDefaults(machine).modules;
	const targetValue = parseValue(projectConfig, "Target", "ROM_32K");
	const target = Targets.find(item => item.value === targetValue);
	if (!target)
		throw new Error(`Project '${projectName}' uses an unsupported program format: ${targetValue}.`);
	const rawRomSize = target.mapped ? readValue(projectConfig, "ROMSize") : undefined;
	const romSize = target.mapped
		? rawRomSize === undefined ? Math.max(128, target.min) : parseIntegerExpression(rawRomSize)
		: undefined;
	if (target.mapped && (!Number.isSafeInteger(romSize) || romSize <= 0))
		throw new Error(`Project '${projectName}' has an unsupported ROMSize expression: ${rawRomSize}.`);
	const rawCompany = readValue(projectConfig, "AppCompany");
	const rawAppID = readValue(projectConfig, "AppID");
	const formatAppValue = raw =>
	{
		if (raw && /^"(?:[^"\\]|\\.)*"$/.test(raw))
			return raw;
		if (raw && /^(?:0x[0-9a-f]+|\d+)$/i.test(raw))
			return raw;
		return "";
	};
	const rawEmulator = readValue(projectConfig, "Emulator");
	const emulator = rawEmulator && /^"(?:[^"\\]|\\.)*"$/.test(rawEmulator)
		? JSON.parse(rawEmulator)
		: "";
	const extensions = EmulatorExtensions
		.filter(([name]) => parseValue(projectConfig, name, false) === true)
		.map(([name]) => name);
	const normalizePort = name => String(parseValue(projectConfig, name, "")).toUpperCase();
	return {
		projectName,
		machine: machine.value,
		target: target.value,
		romSize,
		modes,
		modules,
		installRAMISR: parseValue(projectConfig, "InstallRAMISR", "RAMISR_NONE"),
		customISR: parseValue(projectConfig, "CustomISR", "VBLANK"),
		emulator,
		appSignature: parseValue(projectConfig, "AppSignature", false),
		appCompany: formatAppValue(rawCompany),
		appID: formatAppValue(rawAppID),
		romSkipBoot: parseValue(projectConfig, "ROMSkipBoot", "SKIP_NONE"),
		romSkipBootKey: parseValue(projectConfig, "ROMSkipBootKey", "ESC"),
		CheckVersion: parseValue(projectConfig, "CheckVersion", false),
		ROMDelayBoot: parseValue(projectConfig, "ROMDelayBoot", false),
		AddROMSignature: parseValue(projectConfig, "AddROMSignature", false),
		Verbose: parseValue(projectConfig, "Verbose", false),
		LogStdout: parseValue(projectConfig, "LogStdout", true),
		LogFile: parseValue(projectConfig, "LogFile", false),
		LogFileName: parseValue(projectConfig, "LogFileName", ""),
		Analyzer: parseValue(projectConfig, "Analyzer", false),
		AnalyzerOutput: parseValue(projectConfig, "AnalyzerOutput", "Both"),
		AnalyzerReport: parseValue(projectConfig, "AnalyzerReport", "ASMCV"),
		AnalyzerSort: parseValue(projectConfig, "AnalyzerSort", "Size"),
		AnalyzerCSV: parseValue(projectConfig, "AnalyzerCSV", false),
		AnalyzerSeparator: parseValue(projectConfig, "AnalyzerSeparator", ","),
		Standalone: parseValue(projectConfig, "Standalone", false),
		extensions,
		emul2ndCart: parseValue(projectConfig, "Emul2ndCart", ""),
		emulPortA: normalizePort("EmulPortA"),
		emulPortB: normalizePort("EmulPortB"),
		advanced: true
	};
}

function saveProjectOptions(form)
{
	const project = getProjectDirectory(form.projectName);
	const configured = configureProject(
		form,
		form.projectName,
		fs.readFileSync(project.projectConfigPath, "utf8"),
		fs.readFileSync(project.msxglConfigPath, "utf8")
	);
	fs.writeFileSync(project.projectConfigPath, configured.projectConfig);
	fs.writeFileSync(project.msxglConfigPath, configured.msxglConfig);
	return { projectName: form.projectName, projectPath: project.projectDir };
}

function validateBuildActions(actions, allowEmpty = false)
{
	if (!Array.isArray(actions) || (!allowEmpty && actions.length === 0) ||
		actions.some(action => !BuildActions.includes(action)) ||
		new Set(actions).size !== actions.length)
		throw new Error(allowEmpty ? "Select valid build actions." : "Select one or more build actions.");
	return [...actions];
}

function getBuildInvocation(projectName, actions)
{
	validateBuildActions(actions);
	const { projectDir } = getProjectDirectory(projectName);
	if (!fs.existsSync(path.join(projectDir, "build.bat")) &&
		!fs.existsSync(path.join(projectDir, "build.sh")))
		throw new Error(`No build script was found for '${projectName}'.`);

	const args = [BuildScript, "none", ...actions];
	const quote = value => `"${String(value).replace(/"/g, '\\"')}"`;
	return {
		projectDir,
		args,
		commandLine: [process.execPath, ...args].map(quote).join(" ")
	};
}

function buildProject(projectName, actions)
{
	const invocation = getBuildInvocation(projectName, actions);
	const { projectDir } = invocation;
	if (ActiveBuildProjects.has(projectName))
		throw new Error(`A build is already running for '${projectName}'.`);

	const job = {
		id: crypto.randomUUID(),
		projectName,
		startedAt: Date.now(),
		output: "",
		outputTruncated: false,
		done: false,
		success: false,
		error: ""
	};
	BuildJobs.set(job.id, job);
	ActiveBuildProjects.add(projectName);
	const child = spawn(process.execPath, invocation.args, {
		cwd: projectDir,
		windowsHide: true,
		stdio: ["ignore", "pipe", "pipe"]
	});
	const capture = chunk =>
	{
		const text = chunk.toString("utf8");
		const remaining = MaxBuildOutput - job.output.length;
		if (remaining > 0)
		{
			job.output += text.slice(0, remaining);
		}
		if (text.length > remaining)
			job.outputTruncated = true;
	};
	child.stdout.on("data", capture);
	child.stderr.on("data", capture);
	child.once("error", error =>
	{
		job.done = true;
		job.error = `Could not start the build process: ${error.message}`;
		ActiveBuildProjects.delete(projectName);
	});
	child.once("close", (code, signal) =>
	{
		job.done = true;
		job.success = code === 0 && !signal;
		if (!job.success)
		{
			const reason = signal ? `signal ${signal}` : `exit code ${code}`;
			job.error = `Build failed with ${reason}.`;
		}
		ActiveBuildProjects.delete(projectName);
	});

	for (const [jobId, existingJob] of BuildJobs)
	{
		if (existingJob.done && Date.now() - existingJob.startedAt > BuildJobRetention)
			BuildJobs.delete(jobId);
	}

	return { jobId: job.id, projectName };
}

function getBuildJob(jobId, offset)
{
	const job = BuildJobs.get(jobId);
	if (!job)
		throw new Error("Build job not found or expired.");
	if (!Number.isSafeInteger(offset) || offset < 0 || offset > job.output.length)
		throw new Error("Invalid build output position.");
	return {
		jobId: job.id,
		projectName: job.projectName,
		done: job.done,
		success: job.success,
		error: job.error,
		output: job.output.slice(offset),
		nextOffset: job.output.length,
		outputTruncated: job.outputTruncated
	};
}

function sendJson(response, statusCode, value)
{
	response.writeHead(statusCode, {
		"Content-Type": "application/json; charset=utf-8",
		"Cache-Control": "no-store",
		"X-Content-Type-Options": "nosniff"
	});
	response.end(JSON.stringify(value));
}

function readJsonRequest(request)
{
	return new Promise((resolve, reject) =>
	{
		let body = "";
		let tooLarge = false;
		request.setEncoding("utf8");
		request.on("data", chunk =>
		{
			if (tooLarge)
				return;
			body += chunk;
			if (Buffer.byteLength(body) > MaxRequestSize)
			{
				tooLarge = true;
				body = "";
			}
		});
		request.on("end", () =>
		{
			if (tooLarge)
			{
				reject(new Error("Form submission is too large."));
				return;
			}
			try
			{
				resolve(JSON.parse(body));
			}
			catch
			{
				reject(new Error("The submitted form data is invalid."));
			}
		});
		request.on("error", reject);
	});
}

function browseForFile(title, filter)
{
	if (process.platform !== "win32")
		return Promise.reject(new Error("The file browser is currently available on Windows only."));

	const script = [
		"Add-Type -AssemblyName System.Windows.Forms",
		"$dialog = New-Object System.Windows.Forms.OpenFileDialog",
		`$dialog.Title = '${title.replace(/'/g, "''")}'`,
		`$dialog.Filter = '${filter.replace(/'/g, "''")}'`,
		"$dialog.CheckFileExists = $true",
		"if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { [Console]::Write($dialog.FileName) }",
		"$dialog.Dispose()"
	].join("; ");

	return new Promise((resolve, reject) =>
	{
		const child = spawn("powershell.exe", ["-NoProfile", "-STA", "-WindowStyle", "Hidden", "-Command", script], {
			windowsHide: true,
			stdio: ["ignore", "pipe", "pipe"]
		});
		let output = "";
		let errorOutput = "";
		child.stdout.setEncoding("utf8");
		child.stderr.setEncoding("utf8");
		child.stdout.on("data", chunk => output += chunk);
		child.stderr.on("data", chunk => errorOutput += chunk);
		child.once("error", reject);
		child.once("close", code =>
		{
			if (code !== 0)
			{
				reject(new Error(`Could not open the emulator file browser.${errorOutput.trim() ? ` ${errorOutput.trim()}` : ""}`));
				return;
			}
			resolve(output.trim());
		});
	});
}

function browseForEmulator()
{
	return browseForFile("Select the emulator executable", "Executable files (*.exe)|*.exe|All files (*.*)|*.*");
}

function browseForSecondCart()
{
	return browseForFile("Select the secondary cartridge ROM", "ROM files (*.rom;*.mx1;*.mx2)|*.rom;*.mx1;*.mx2|All files (*.*)|*.*");
}

function createServer()
{
	let shutdownTimer;
	const server = http.createServer(async (request, response) =>
	{
		try
		{
			if (request.socket.remoteAddress !== "127.0.0.1" && request.socket.remoteAddress !== "::ffff:127.0.0.1")
				return sendJson(response, 403, { error: "Only local browser requests are allowed." });
			const address = server.address();
			if (!address || request.headers.host !== `127.0.0.1:${address.port}`)
				return sendJson(response, 403, { error: "Unexpected local host header." });
			if (shutdownTimer)
			{
				clearTimeout(shutdownTimer);
				shutdownTimer = undefined;
			}

			const requestUrl = new URL(request.url, "http://127.0.0.1");
			if (request.method === "POST" && requestUrl.pathname === "/api/close")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}`)
					return sendJson(response, 403, { error: "Wizard shutdown must be requested from this local page." });
				response.writeHead(204);
				response.end();
				shutdownTimer = setTimeout(() => server.close(), 2000);
				shutdownTimer.unref();
				return;
			}

			if (request.method === "GET" && requestUrl.pathname === "/")
			{
				response.writeHead(200, {
					"Content-Type": "text/html; charset=utf-8",
					"Cache-Control": "no-store",
					"X-Content-Type-Options": "nosniff",
					"Referrer-Policy": "no-referrer",
					"Content-Security-Policy": "default-src 'self'; style-src 'self'; script-src 'self' 'unsafe-inline'; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"
				});
				return response.end(fs.readFileSync(FormPath));
			}

			if (request.method === "GET" && requestUrl.pathname === "/wizard.css")
			{
				response.writeHead(200, {
					"Content-Type": "text/css; charset=utf-8",
					"Cache-Control": "no-store",
					"X-Content-Type-Options": "nosniff"
				});
				return response.end(fs.readFileSync(StylePath));
			}

			const translationMatch = request.method === "GET" &&
				requestUrl.pathname.match(/^\/translation_(en|fr|es|nl|pt-BR|it|ja)\.js$/);
			if (translationMatch)
			{
				const translationPath = path.join(WizardDir, `translation_${translationMatch[1]}.js`);
				response.writeHead(200, {
					"Content-Type": "application/javascript; charset=utf-8",
					"Cache-Control": "no-store",
					"X-Content-Type-Options": "nosniff"
				});
				return response.end(fs.readFileSync(translationPath));
			}

			if (request.method === "GET" && requestUrl.pathname === "/msxgl-logo.png")
			{
				response.writeHead(200, {
					"Content-Type": "image/png",
					"Cache-Control": "no-store",
					"X-Content-Type-Options": "nosniff"
				});
				return response.end(fs.readFileSync(LogoPath));
			}

			if (request.method === "GET" && requestUrl.pathname === "/api/options")
				return sendJson(response, 200, getOptions(requestUrl.searchParams.get("machine") || "1"));

			if (request.method === "GET" && requestUrl.pathname === "/api/state")
				return sendJson(response, 200, { ...readWizardConfig(), projects: listProjects() });

			if (request.method === "POST" && requestUrl.pathname === "/api/state")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}` ||
					!String(request.headers["content-type"] || "").startsWith("application/json"))
					return sendJson(response, 403, { error: "Wizard settings must be saved from this local page." });
				return sendJson(response, 200, saveWizardConfig(await readJsonRequest(request)));
			}

			if (request.method === "GET" && requestUrl.pathname === "/api/project-options")
				return sendJson(response, 200, getProjectSettings(requestUrl.searchParams.get("name")));

			if (request.method === "POST" && requestUrl.pathname === "/api/build-command")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}` ||
					!String(request.headers["content-type"] || "").startsWith("application/json"))
					return sendJson(response, 403, { error: "Build command preview must be requested from this local page." });
				const form = await readJsonRequest(request);
				const invocation = getBuildInvocation(form.projectName, form.actions);
				return sendJson(response, 200, {
					commandLine: invocation.commandLine,
					workingDirectory: invocation.projectDir
				});
			}

			if (request.method === "POST" && requestUrl.pathname === "/api/save-options")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}` ||
					!String(request.headers["content-type"] || "").startsWith("application/json"))
					return sendJson(response, 403, { error: "Project options must be saved from this local page." });
				const form = await readJsonRequest(request);
				saveWizardConfig({ lastOption: "edit", projectName: form.projectName, language: form.language });
				return sendJson(response, 200, saveProjectOptions(form));
			}

			if (request.method === "POST" && requestUrl.pathname === "/api/build")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}` ||
					!String(request.headers["content-type"] || "").startsWith("application/json"))
					return sendJson(response, 403, { error: "Builds must be started from this local page." });
				const form = await readJsonRequest(request);
				const actions = validateBuildActions(form.actions);
				saveWizardConfig({
					lastOption: "build",
					projectName: form.projectName,
					language: form.language,
					buildActions: actions
				});
				return sendJson(response, 202, buildProject(form.projectName, actions));
			}

			if (request.method === "GET" && requestUrl.pathname.startsWith("/api/build/"))
			{
				const jobId = requestUrl.pathname.slice("/api/build/".length);
				const offset = Number(requestUrl.searchParams.get("offset") || "0");
				const result = getBuildJob(jobId, offset);
				return sendJson(response, 200, result);
			}

			if (request.method === "POST" && requestUrl.pathname === "/api/browse-emulator")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}`)
					return sendJson(response, 403, { error: "File browsing must be requested from this local wizard page." });
				return sendJson(response, 200, { path: await browseForEmulator() });
			}

			if (request.method === "POST" && requestUrl.pathname === "/api/browse-second-cart")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}`)
					return sendJson(response, 403, { error: "File browsing must be requested from this local wizard page." });
				return sendJson(response, 200, { path: await browseForSecondCart() });
			}

			if (request.method === "POST" && requestUrl.pathname === "/api/create")
			{
				if (request.headers.origin !== `http://127.0.0.1:${address.port}` ||
					!String(request.headers["content-type"] || "").startsWith("application/json"))
					return sendJson(response, 403, { error: "Form submission must come from this local wizard page." });
				const form = await readJsonRequest(request);
				saveWizardConfig({ lastOption: "create", projectName: form.projectName, language: form.language });
				const result = createProject(form);
				return sendJson(response, 201, result);
			}

			sendJson(response, 404, { error: "Not found." });
		}
		catch (error)
		{
			if (!response.headersSent)
				sendJson(response, 400, { error: error.message });
			else
				response.destroy(error);
		}
	});

	return server;
}

function startBackgroundServer()
{
	const server = createServer();
	server.listen(0, "127.0.0.1", () =>
	{
		const address = server.address();
		process.stdout.write(`READY http://127.0.0.1:${address.port}/\n`);
		process.stdout.end();
	});
	server.on("error", error =>
	{
		if (!process.stdout.writableEnded)
		{
			process.stdout.write(`ERROR ${error.message}\n`);
			process.stdout.end();
		}
	});
}

function launchBackgroundServer()
{
	return new Promise((resolve, reject) =>
	{
		const child = spawn(process.execPath, [__filename, "--server"], {
			detached: true,
			stdio: ["ignore", "pipe", "ignore"],
			windowsHide: true
		});
		let output = "";
		let settled = false;
		const timeout = setTimeout(() =>
		{
			if (settled)
				return;
			settled = true;
			child.kill();
			reject(new Error("The wizard server did not start in time."));
		}, 15000);
		const finish = (error, url) =>
		{
			if (settled)
				return;
			settled = true;
			clearTimeout(timeout);
			child.stdout.destroy();
			if (error)
				reject(error);
			else
				resolve(url);
		};

		child.once("error", error => finish(error));
		child.once("exit", code =>
		{
			if (!settled)
				finish(new Error(`The wizard server stopped before startup (exit code ${code}).`));
		});
		child.stdout.setEncoding("utf8");
		child.stdout.on("data", chunk =>
		{
			output += chunk;
			const lineEnd = output.indexOf("\n");
			if (lineEnd < 0)
				return;
			const line = output.slice(0, lineEnd).trim();
			if (line.startsWith("READY "))
				finish(undefined, line.slice("READY ".length));
			else if (line.startsWith("ERROR "))
				finish(new Error(line.slice("ERROR ".length)));
		});
		child.unref();
	});
}

function openBrowser(url)
{
	let command;
	let args;
	if (process.platform === "win32")
	{
		command = process.env.ComSpec || "cmd.exe";
		args = ["/c", "start", "", url];
	}
	else if (process.platform === "darwin")
	{
		command = "open";
		args = [url];
	}
	else
	{
		command = "xdg-open";
		args = [url];
	}

	return new Promise((resolve, reject) =>
	{
		const child = spawn(command, args, { detached: true, stdio: "ignore", windowsHide: true });
		child.once("error", reject);
		child.once("spawn", () =>
		{
			child.unref();
			resolve();
		});
	});
}

async function main()
{
	if (process.argv.includes("--server"))
	{
		startBackgroundServer();
		return;
	}

	if (process.platform === "win32" && !process.argv.includes("--no-open"))
	{
		const url = await launchBackgroundServer();
		console.log(`MSXgl project wizard: ${url}`);
		try
		{
			await openBrowser(url);
		}
		catch (error)
		{
			console.error(`Could not open the default browser: ${error.message}`);
			console.error(`Open this address manually: ${url}`);
		}
		return;
	}

	const server = createServer();
	server.on("error", error => console.error(`Wizard server error: ${error.message}`));
	server.listen(0, "127.0.0.1", async () =>
	{
		const address = server.address();
		const url = `http://127.0.0.1:${address.port}/`;
		console.log(`MSXgl project wizard: ${url}`);
		try
		{
			if (!process.argv.includes("--no-open"))
				await openBrowser(url);
			console.log("Complete the form in your browser. The wizard stays open for additional actions; close this window to exit.");
		}
		catch (error)
		{
			console.error(`Could not open the default browser: ${error.message}`);
			console.error(`Open this address manually: ${url}`);
		}
	});
}

if (require.main === module)
	main().catch(error =>
	{
		console.error(`Wizard error: ${error.message}`);
		process.exitCode = 1;
	});

module.exports = {
	buildProject,
	createProject,
	createServer,
	getBuildJob,
	getOptions,
	getProjectSettings,
	listProjects,
	saveProjectOptions
};
